import 'package:flutter/material.dart';import '../core/utils/formatters.dart';import '../data/repositories/expense_repository.dart';
class BudgetsScreen extends StatefulWidget{const BudgetsScreen({super.key,required this.onChanged});final VoidCallback onChanged;@override State<BudgetsScreen> createState()=>_BudgetsScreenState();}
class _BudgetsScreenState extends State<BudgetsScreen>{final repo=ExpenseRepository();late Future<_Data> future;String get month=>DateTime.now().year.toString()+'-'+DateTime.now().month.toString().padLeft(2,'0');@override void initState(){super.initState();future=load();}Future<_Data> load()async=>_Data(await repo.budgets(month),await repo.categories(type:'expense'));void reload()=>setState(()=>future=load());
 @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Monthly budgets')),body:FutureBuilder<_Data>(future:future,builder:(context,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());final d=s.data!,limit=d.rows.fold<int>(0,(v,e)=>v+(e['amount_minor'] as int)),spent=d.rows.fold<int>(0,(v,e)=>v+(e['spent_minor'] as int));return ListView(padding:const EdgeInsets.all(18),children:[
 Container(padding:const EdgeInsets.all(20),decoration:BoxDecoration(color:const Color(0xFF17211F),borderRadius:BorderRadius.circular(20)),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(Fmt.month(DateTime.now()),style:const TextStyle(color:Colors.white60)),const SizedBox(height:10),Text(Fmt.money(spent/100),style:const TextStyle(color:Colors.white,fontSize:28,fontWeight:FontWeight.w800)),Text('of '+Fmt.money(limit/100)+' planned',style:const TextStyle(color:Colors.white60)),const SizedBox(height:12),LinearProgressIndicator(value:limit==0?0:(spent/limit).clamp(0,1),color:const Color(0xFF72D6B3),backgroundColor:Colors.white24)])),
 Row(children:[Text('Category limits',style:Theme.of(context).textTheme.titleLarge),const Spacer(),TextButton.icon(onPressed:()=>addBudget(d.cats),icon:const Icon(Icons.add),label:const Text('Set budget'))]),
 if(d.rows.isEmpty)const Text('No budgets set for this month.')else ...d.rows.map((e){final cap=e['amount_minor'] as int,used=e['spent_minor'] as int,over=used>cap;return Card(child:Padding(padding:const EdgeInsets.all(15),child:Column(children:[Row(children:[Expanded(child:Text(e['category_name'] as String,style:const TextStyle(fontWeight:FontWeight.w700))),Text(Fmt.money(used/100)+' / '+Fmt.money(cap/100))]),const SizedBox(height:10),LinearProgressIndicator(value:cap==0?0:(used/cap).clamp(0,1),color:over?Colors.red:const Color(0xFF167D62)),const SizedBox(height:6),Align(alignment:Alignment.centerRight,child:Text(over?'Over budget':'Remaining: '+Fmt.money((cap-used).clamp(0,cap)/100),style:TextStyle(color:over?Colors.red:Colors.grey,fontSize:12)))])));})
 ]);}));
 Future<void> addBudget(List<Map<String,Object?>> cats)async{if(cats.isEmpty)return;int selected=cats.first['id'] as int;final amount=TextEditingController();final ok=await showDialog<bool>(context:context,builder:(c)=>StatefulBuilder(builder:(c,setD)=>AlertDialog(title:const Text('Set monthly budget'),content:Column(mainAxisSize:MainAxisSize.min,children:[DropdownButtonFormField<int>(value:selected,items:cats.map((e)=>DropdownMenuItem(value:e['id'] as int,child:Text(e['name'] as String))).toList(),onChanged:(v)=>setD(()=>selected=v!)),TextField(controller:amount,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Monthly limit',prefixText:'₹ '))]),actions:[TextButton(onPressed:()=>Navigator.pop(c,false),child:const Text('Cancel')),TextButton(onPressed:()=>Navigator.pop(c,true),child:const Text('Save'))])));final n=double.tryParse(amount.text);if(ok==true&&n!=null&&n>0){await repo.saveBudget(selected,(n*100).round(),month);widget.onChanged();reload();}amount.dispose();}
}
class _Data{_Data(this.rows,this.cats);final List<Map<String,Object?>> rows,cats;}
